def get_row(row_index):
    triangle = [[1]]                        # start with row 0
    for i in range(1, row_index + 1):
        prev = triangle[-1]
        current = [1] * (i + 1)               # every row starts filled with 1s at both edges
        for j in range(1, i):
            current[j] = prev[j - 1] + prev[j]  # sum the two values above
        triangle.append(current)              # keep every row, even ones we'll never use again
    return triangle[row_index]               # only the very last row is actually needed


if __name__ == "__main__":
    row_index = 3
    print(get_row(row_index))

