import java.util.*;

public class Main {
    List<Integer> getRow(int rowIndex) {
        List<List<Integer>> triangle = new ArrayList<>();
        triangle.add(new ArrayList<>(List.of(1)));       // start with row 0
        for (int i = 1; i <= rowIndex; i++) {
            List<Integer> prev = triangle.get(triangle.size() - 1);
            List<Integer> current = new ArrayList<>(Collections.nCopies(i + 1, 1)); // start filled with 1s
            for (int j = 1; j < i; j++) {
                current.set(j, prev.get(j - 1) + prev.get(j));  // sum the two values above
            }
            triangle.add(current);                              // keep every row, even ones we'll never use again
        }
        return triangle.get(rowIndex);                         // only the very last row is actually needed
    }

    public static void main(String[] args) {
        int rowIndex = 3;
        Main solution = new Main();
        System.out.println(solution.getRow(rowIndex));
    }
}

